package main

import "github.com/corentings/chess/v2"

const aspirationWindow = 50

// Only a completed in-window probe is exact. A bound failure receives one full
// retry; an interrupted probe/retry leaves the caller's prior result intact.
func (worker *searcher) aspirationRoot(position *chess.Position, moves []chess.Move, depth, previous int) ([]string, int, bool) {
	if depth < 3 || abs(previous) >= mateBound {
		return worker.root(position, moves, depth)
	}
	alpha, beta := previous-aspirationWindow, previous+aspirationWindow
	best, score, complete := worker.rootWindow(position, moves, depth, alpha, beta)
	if !complete {
		return nil, 0, false
	}
	if score <= alpha || score >= beta {
		return worker.root(position, moves, depth)
	}
	return best, score, true
}

