package main

import (
	"context"
	"reflect"
	"slices"
	"testing"
	"time"

	"github.com/corentings/chess/v2"
)

func aspirationWorker() *searcher { return &searcher{table: newTable(), killers: new(killerTable)} }

func TestAspirationExactScoresAndBoundRecovery(t *testing.T) {
	for _, fen := range []string{chess.StartingPosition().String(), queenRaidPosition, "4k3/8/8/8/8/8/8/3QK3 w - - 0 1", "7k/5Q2/5K2/8/8/8/8/8 w - - 0 1"} {
		p := evalFEN(t, fen)
		moves := rootMoves(p, nil)
		best, score := fullWindowRoot(t, p, moves, 3, nil)
		for _, previous := range []int{score, score - 50, score + 50, score - 500, score + 500, mateScore, -mateScore} {
			w := aspirationWorker()
			got, value, ok := w.aspirationRoot(p, moves, 3, previous)
			if !ok || value != score || len(got) != 1 || !slices.Contains(best, got[0]) {
				t.Fatal("aspiration changed exact value/best membership", fen, previous, got, value, best, score)
			}
			manual := aspirationWorker()
			var want []string
			var v int
			var complete bool
			if abs(previous) >= mateBound {
				want, v, complete = manual.root(p, moves, 3)
			} else {
				alpha, beta := previous-50, previous+50
				want, v, complete = manual.rootWindow(p, moves, 3, alpha, beta)
				if complete && (v <= alpha || v >= beta) {
					want, v, complete = manual.root(p, moves, 3)
				}
			}
			if !complete || v != value || !reflect.DeepEqual(got, want) || w.nodes != manual.nodes {
				t.Fatal("probe/retry protocol differs", fen, previous)
			}
			if w.historyKey != 0 || len(w.repetitions) != 0 {
				t.Fatal("aspiration leaked history")
			}
		}
	}
}

func TestAspirationEarlyDepthAndMateBypass(t *testing.T) {
	p := chess.StartingPosition()
	moves := rootMoves(p, nil)
	for _, x := range []struct{ depth, previous int }{{1, 1000}, {2, -1000}, {3, mateScore}, {3, -mateScore}} {
		a, b := aspirationWorker(), aspirationWorker()
		got, score, ok := a.aspirationRoot(p, moves, x.depth, x.previous)
		want, value, complete := b.root(p, moves, x.depth)
		if !ok || !complete || score != value || !reflect.DeepEqual(got, want) || a.nodes != b.nodes {
			t.Fatal("bypass altered full search", x)
		}
	}
}

func TestAspirationCancellationDuringProbeAndRetry(t *testing.T) {
	p := chess.StartingPosition()
	fen, hash := p.String(), p.ZobristHash()
	moves := rootMoves(p, nil)
	_, score, _ := aspirationWorker().root(p, moves, 3)
	previous := score + 1000
	start := time.Unix(100, 0)
	calls := 0
	reference := aspirationWorker()
	reference.deadline = start.Add(time.Second)
	reference.now = func() time.Time { calls++; return start }
	_, bound, ok := reference.rootWindow(p, moves, 3, previous-50, previous+50)
	if !ok || bound > previous-50 {
		t.Fatal("fail-low cancellation setup")
	}
	probeCalls := calls
	for _, limit := range []int{10, probeCalls + 3} {
		w := aspirationWorker()
		w.deadline = start.Add(time.Second)
		calls := 0
		w.now = func() time.Time {
			calls++
			if calls > limit {
				return start.Add(2 * time.Second)
			}
			return start
		}
		if _, _, complete := w.aspirationRoot(p, moves, 3, previous); complete {
			t.Fatal("interrupted aspiration accepted", limit)
		}
		if w.historyKey != 0 || len(w.repetitions) != 0 || p.String() != fen || p.ZobristHash() != hash {
			t.Fatal("interrupted aspiration leaked state")
		}
	}
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	w := aspirationWorker()
	w.ctx = ctx
	if _, _, ok := w.aspirationRoot(p, moves, 3, score); ok {
		t.Fatal("canceled aspiration completed")
	}
}

func TestAspirationIncompletePassKeepsPreviousResult(t *testing.T) {
	p := chess.StartingPosition()
	start := time.Unix(100, 0)
	calls := 0
	a := aspirationWorker()
	a.deadline = start.Add(time.Second)
	a.now = func() time.Time { calls++; return start }
	want := a.iterate(p, rootMoves(p, nil), 2, timeBudget{}, start)
	limit := calls + 10
	b := aspirationWorker()
	b.deadline = start.Add(time.Second)
	calls = 0
	b.now = func() time.Time {
		calls++
		if calls > limit {
			return start.Add(2 * time.Second)
		}
		return start
	}
	got := b.iterate(p, rootMoves(p, nil), 3, timeBudget{}, start)
	if got.depth != 2 || got.move != want.move || got.score != want.score {
		t.Fatal("partial aspiration replaced completed result", got, want)
	}
}

